"""generator — PPMI-like panels generated by the expert DAG (Arm A, PROTOCOL.md §6.1).

The data-generating process is the expert DAG run forward year by year for each participant:

    baseline: context (cohort) -> exogenous and baseline nodes, trait -> dat0
    year 0:   every time-varying node from its same-year parents, baseline parents, context and the trait
    year s:   from its own value at s-1 (autoregression), lagged parents at s-1, same-year parents at s (a non-dose
              cause of a dose acts from s-1), baseline parents, context, the year s and the trait

Every node is a Gaussian-copula variable. Its latent score z is a function of its parents' *observed* values on the
normal-score scale, s(x) = Phi^-1(F(x)) under the node's pooled marginal F, plus the trait, an optional person
effect and noise; the observed value is x = F^-1(Phi(z)). Parents act through their observed values (not their
latent scores), so the expert DAG over the observed variables is the exact truth; F reproduces each variable's
type: binary, ordinal sums, counts, continuous, and doses with a point mass at zero.

Two function classes share the DAG (the design's check that rankings do not depend on one model class):
- G1: linear in the parents' scores, Gaussian noise.
- G2: nonlinear: additive non-monotone transforms of the parents with heavy-tailed noise (synthetic spec), or
  gradient-boosted regressions with resampled out-of-fold residuals when fitted to PPMI (`fit`).

`synthetic()` builds a generator from the expert DAG alone, with PPMI-like marginals and effect sizes written into
the code: the harness runs end to end without PPMI. `fit()` estimates one from a PPMI long panel (gated: PROTOCOL.md
§11); a fitted generator holds aggregates only (coefficients, quantile tables, loadings) and is still stored under
data/derived/.
"""
import copy
from dataclasses import dataclass, field

import networkx as nx
import numpy as np
import pandas as pd
from scipy.stats import norm

from . import expert as E

Q_GRID = np.linspace(0.0, 1.0, 201)


# ---------------------------------------------------------------------------- marginals
@dataclass
class Marginal:
    """Pooled marginal of one variable: discrete levels with probabilities, or a quantile table, with an optional
    point mass at zero (doses, months on levodopa, cumulative dose)."""
    kind: str                              # 'discrete' | 'continuous'
    levels: np.ndarray | None = None
    probs: np.ndarray | None = None
    q: np.ndarray | None = None            # quantiles of the continuous part at Q_GRID
    p0: float = 0.0                        # point mass at 0 (continuous kind only)

    def ppf(self, u):
        u = np.clip(u, 1e-9, 1 - 1e-9)
        if self.kind == "discrete":
            idx = np.searchsorted(np.cumsum(self.probs), u, side="right")
            return self.levels[np.minimum(idx, len(self.levels) - 1)].astype(float)
        if self.p0 > 0:
            pos = np.interp((u - self.p0) / (1 - self.p0), Q_GRID, self.q)
            return np.where(u < self.p0, 0.0, pos)
        return np.interp(u, Q_GRID, self.q)

    def score(self, x):
        """Normal score s(x) = Phi^-1(F_mid(x)): the mid-probability of a discrete level (or of the zero mass)."""
        x = np.asarray(x, dtype=float)
        out = np.full(x.shape, np.nan)
        ok = ~np.isnan(x)
        if self.kind == "discrete":
            cum = np.cumsum(self.probs)
            mid = cum - self.probs / 2
            idx = np.clip(np.searchsorted(self.levels, x[ok]), 0, len(self.levels) - 1)
            out[ok] = norm.ppf(np.clip(mid[idx], 1e-6, 1 - 1e-6))
            return out
        xv = x[ok]
        F = np.interp(xv, self.q, Q_GRID)
        if self.p0 > 0:
            F = np.where(xv <= 0, self.p0 / 2, self.p0 + (1 - self.p0) * F)
        out[ok] = norm.ppf(np.clip(F, 1e-4, 1 - 1e-4))
        return out

    @classmethod
    def from_data(cls, x, kind):
        """Aggregate marginal from observed values (used by `fit`; only level frequencies or 201 quantiles leave
        the data)."""
        x = np.asarray(x, dtype=float)
        x = x[~np.isnan(x)]
        if kind in ("binary", "ordinal", "count") and np.unique(x).size <= 60:
            lv, n = np.unique(x, return_counts=True)
            return cls("discrete", levels=lv, probs=n / n.sum())
        p0 = float(np.mean(x == 0)) if kind == "semicontinuous" else 0.0
        part = x[x > 0] if p0 > 0 else x
        return cls("continuous", q=np.quantile(part, Q_GRID), p0=p0)


def _discrete(levels, weights):
    w = np.asarray(weights, dtype=float)
    return Marginal("discrete", levels=np.asarray(levels, dtype=float), probs=w / w.sum())


def _continuous(sampler, p0=0.0, n=200_000, seed=0):
    rng = np.random.default_rng(seed)
    return Marginal("continuous", q=np.quantile(sampler(rng, n), Q_GRID), p0=p0)


# ---------------------------------------------------------------------------- node models
@dataclass
class NodeModel:
    """Latent equation of one node in one regime ('base', 'year0' or 'trans')."""
    node: str
    inputs: list                      # input keys: '<v>@0' same year, '<v>@1' previous year, baseline/context names, 't'
    coef: np.ndarray                  # linear part (G1) or the weight of each transformed input (synthetic G2)
    intercept: float = 0.0
    transform: list | None = None     # synthetic G2: per-input transform id ('lin', 'sq', 'tanh', 'step')
    booster: object = None            # fitted G2: a regressor on the input scores
    noise: str = "normal"             # 'normal' | 't5' | 'quantile'
    sigma: float = 1.0
    resid_q: np.ndarray | None = None  # fitted G2: out-of-fold residual quantiles at Q_GRID
    trait: float = 0.0                # loading of the latent trait
    person_sd: float = 0.0            # sd of the per-node person effect (person-heterogeneity stress setting)
    loc: float = 0.0                  # calibration: pooled mean and sd of z (set by `calibrate`)
    scale: float = 1.0


_TRANSFORMS = {"lin": lambda s: s, "sq": lambda s: (s ** 2 - 1) / np.sqrt(2), "tanh": lambda s: np.tanh(1.5 * s) * 1.3,
               "step": lambda s: np.where(s > 0.5, 1.0, -0.4)}


def _mean(m: NodeModel, X):
    if m.booster is not None:
        return m.booster.predict(X)
    if m.transform is None:
        return m.intercept + X @ m.coef
    cols = [_TRANSFORMS[t](X[:, j]) for j, t in enumerate(m.transform)]
    return m.intercept + (np.column_stack(cols) @ m.coef if cols else 0.0)


def _noise(m: NodeModel, rng, n):
    if m.noise == "quantile" and m.resid_q is not None:
        return np.interp(rng.random(n), Q_GRID, m.resid_q)
    if m.noise == "t5":
        return m.sigma * rng.standard_t(5, n) / np.sqrt(5 / 3)
    return m.sigma * rng.standard_normal(n)


# ---------------------------------------------------------------------------- the generator
@dataclass
class Generator:
    kind: str                                    # 'G1' | 'G2'
    spec: E.ExpertSpec
    marginals: dict                              # node -> Marginal
    models: dict                                 # (regime, node) -> NodeModel
    context_probs: dict                          # (era2, genetic) -> probability
    followup: dict                               # (era2, genetic) -> (years array, probabilities): grid years observed
    context_edges: tuple                         # (context, node) pairs of the truth
    order0: list = field(default_factory=list)   # topological order within a year (year 0 and later years)
    order_t: list = field(default_factory=list)
    source: str = "synthetic"
    strengths: dict = field(default_factory=dict)   # (input, node) of the 'trans'/'base' regime -> effect strength

    def copy(self):
        return copy.deepcopy(self)


def _same_year_parents(spec, v, year0):
    """Same-year causes of v: a 'same' edge into a dose from a non-dose acts one year later."""
    out = []
    for a, b, kind in spec.edges:
        if b != v or a not in spec.tv or kind not in ("same", "both"):
            continue
        if v in E.DOSE and a not in E.DOSE:
            continue
        out.append(a)
    return out


def _inputs(spec, v, regime, context_edges):
    """Input keys of node v in a regime."""
    base = [a for a, b, kind in spec.edges if b == v and kind == "base" and a in spec.baseline]
    ctx = [c for c, b in context_edges if b == v]
    if regime == "base":
        return ctx
    same = [f"{a}@0" for a in _same_year_parents(spec, v, regime == "year0")]
    if regime == "year0":
        return same + base + ctx
    lag = [f"{a}@1" for a, b, kind in spec.edges if b == v and a in spec.tv and kind in ("lag", "both")]
    lag += [f"{a}@1" for a, b, kind in spec.edges if b == v and a in spec.tv and kind in ("same", "both")
            and v in E.DOSE and a not in E.DOSE]
    return [f"{v}@1"] + sorted(set(lag), key=lag.index) + same + base + ctx + ["t"]


def _within_year_order(spec):
    g = nx.DiGraph()
    g.add_nodes_from(spec.tv)
    for v in spec.tv:
        for a in _same_year_parents(spec, v, False):
            g.add_edge(a, v)
    return list(nx.topological_sort(g))


def trait_children(spec):
    return [b for a, b, kind in spec.edges if a in spec.latent]


# ---------------------------------------------------------------------------- simulation
def simulate(gen: Generator, n: int, seed: int, person_effects: bool = False, max_years: int = 15):
    """Simulate n participants. Returns (long panel: one row per participant-year with PATNO, year and every node,
    baseline table: one row per participant with context, exogenous and baseline nodes)."""
    rng = np.random.default_rng(seed)
    spec = gen.spec
    combos = list(gen.context_probs)
    pick = rng.choice(len(combos), size=n, p=np.array([gen.context_probs[c] for c in combos]))
    era2 = np.array([combos[k][0] for k in pick], dtype=float)
    genetic = np.array([combos[k][1] for k in pick], dtype=float)
    trait = rng.standard_normal(n)
    vals = {"era2": era2, "genetic": genetic}
    scores = {"era2": era2 * 2 - 1, "genetic": genetic * 2 - 1}     # context enters as +-1
    for b in [x for x in E.EXOGENOUS if x != "t"] + list(spec.baseline_disease):
        if b not in spec.baseline:
            continue
        m = gen.models[("base", b)]
        X = _matrix(m.inputs, scores, None, None, n)
        z = _mean(m, X) + m.trait * trait + _noise(m, rng, n)
        x = gen.marginals[b].ppf(norm.cdf((z - m.loc) / m.scale))
        vals[b], scores[b] = x, gen.marginals[b].score(x)
    years = np.zeros(n, dtype=int)
    for k, combo in enumerate(combos):
        sel = pick == k
        yrs, p = gen.followup[combo]
        years[sel] = rng.choice(yrs, size=sel.sum(), p=np.asarray(p, float) / np.sum(p))
    years = np.minimum(years, max_years)
    u = {v: (rng.standard_normal(n) * gen.models[("trans", v)].person_sd if person_effects else np.zeros(n)) for v in spec.tv}
    rows, prev = [], None
    for s in range(int(years.max())):
        cur_x, cur_s = {}, {}
        regime = "year0" if s == 0 else "trans"
        for v in (gen.order0 if s == 0 else gen.order_t):
            m = gen.models[(regime, v)]
            X = _matrix(m.inputs, scores, cur_s, prev, n, t=s)
            z = _mean(m, X) + m.trait * trait + u[v] + _noise(m, rng, n)
            x = gen.marginals[v].ppf(norm.cdf((z - m.loc) / m.scale))
            cur_x[v], cur_s[v] = x, gen.marginals[v].score(x)
        alive = years > s
        df = pd.DataFrame({k: v[alive] for k, v in cur_x.items()})
        df.insert(0, "year", s)
        df.insert(0, "PATNO", np.nonzero(alive)[0])
        rows.append(df)
        prev = cur_s
    long = pd.concat(rows, ignore_index=True).sort_values(["PATNO", "year"]).reset_index(drop=True)
    base = pd.DataFrame({"PATNO": np.arange(n), **{k: v for k, v in vals.items()}})
    return long, base


def _matrix(inputs, base_scores, cur, prev, n, t=0):
    cols = []
    for key in inputs:
        if key == "t":
            cols.append(np.full(n, float(t)))
        elif key.endswith("@0"):
            cols.append(cur[key[:-2]])
        elif key.endswith("@1"):
            cols.append(prev[key[:-2]])
        else:
            cols.append(base_scores[key])
    return np.column_stack(cols) if cols else np.zeros((n, 0))


def calibrate(gen: Generator, n: int = 4000, passes: int = 40, seed: int = 999, damping: float = 0.5, tol: float = 0.005):
    """Set each node's (loc, scale) to the pooled mean and sd of its latent score over a pilot cohort, so the pooled
    marginal of every simulated variable matches its target marginal. Parents' scores feed children, and the plain
    fixed-point iteration oscillates (levodopa and its children push each other's constants back and forth), so each
    pass moves the constants halfway to the pilot's values until no constant moves by more than `tol`."""
    spec = gen.spec
    for _ in range(passes):
        moved = 0.0
        rng = np.random.default_rng(seed)
        acc = {}
        combos = list(gen.context_probs)
        pick = rng.choice(len(combos), size=n, p=np.array([gen.context_probs[c] for c in combos]))
        era2 = np.array([combos[k][0] for k in pick], dtype=float)
        genetic = np.array([combos[k][1] for k in pick], dtype=float)
        trait = rng.standard_normal(n)
        scores = {"era2": era2 * 2 - 1, "genetic": genetic * 2 - 1}
        for b in [x for x in E.EXOGENOUS if x != "t"] + list(spec.baseline_disease):
            if b not in spec.baseline:
                continue
            m = gen.models[("base", b)]
            z = _mean(m, _matrix(m.inputs, scores, None, None, n)) + m.trait * trait + _noise(m, rng, n)
            acc[("base", b)] = [z]
            scores[b] = gen.marginals[b].score(gen.marginals[b].ppf(norm.cdf((z - m.loc) / m.scale)))
        years = np.zeros(n, dtype=int)
        for k, combo in enumerate(combos):
            sel = pick == k
            yrs, p = gen.followup[combo]
            years[sel] = rng.choice(yrs, size=sel.sum(), p=np.asarray(p, float) / np.sum(p))
        prev = None
        for s in range(int(years.max())):
            cur = {}
            regime = "year0" if s == 0 else "trans"
            alive = years > s
            for v in (gen.order0 if s == 0 else gen.order_t):
                m = gen.models[(regime, v)]
                z = _mean(m, _matrix(m.inputs, scores, cur, prev, n, t=s)) + m.trait * trait + _noise(m, rng, n)
                acc.setdefault((regime, v), []).append(z[alive])
                cur[v] = gen.marginals[v].score(gen.marginals[v].ppf(norm.cdf((z - m.loc) / m.scale)))
            prev = cur
        # one location and scale per node, pooled over its regimes, so the year-0 shift relative to later years
        # (no one on levodopa at enrolment in PPMI 1.0) survives the calibration
        for node in {k[1] for k in acc}:
            zs = np.concatenate([np.concatenate(acc[k]) for k in acc if k[1] == node])
            for k in [k for k in acc if k[1] == node]:
                m = gen.models[k]
                loc = (1 - damping) * m.loc + damping * float(zs.mean())
                scale = (1 - damping) * m.scale + damping * float(zs.std() + 1e-9)
                moved = max(moved, abs(loc - m.loc), abs(scale - m.scale) / max(m.scale, 1e-9))
                m.loc, m.scale = loc, scale
        if moved < tol:
            break
    gen.calibration_passes = _ + 1
    return gen


def two_slice(long: pd.DataFrame, base: pd.DataFrame, spec: E.ExpertSpec):
    """Rows (participant, year t) with year t+1 observed: context, exogenous and baseline nodes, t, X_t (_0), X_t+1 (_1)."""
    a = long.copy()
    b = long.copy()
    b["year"] -= 1
    m = a.merge(b, on=["PATNO", "year"], suffixes=("_0", "_1"))
    m = m.merge(base, on="PATNO", how="left")
    m["t"] = m.year.astype(float)
    cols = ["PATNO"] + E.two_slice_names(spec)
    return m[[c for c in cols if c in m.columns]].reset_index(drop=True)


# ---------------------------------------------------------------------------- effect strengths (near-zero flags)
def strengths(gen: Generator, n: int = 3000, seed: int = 4242):
    """Strength of every input of the 'trans' and 'base' equations: sqrt of the drop in R^2 of the node's latent score
    when that input is permuted across rows (pilot cohort; the same definition for G1 and G2). PROTOCOL.md §6.4 flags
    an edge as near zero below 0.05."""
    rng = np.random.default_rng(seed)
    long, base = simulate(gen, n, seed)
    spec = gen.spec
    sc_base = {"era2": base.era2.to_numpy() * 2 - 1, "genetic": base.genetic.to_numpy() * 2 - 1}
    for b in spec.baseline:
        sc_base[b] = gen.marginals[b].score(base[b].to_numpy())
    out = {}
    nxt = long.copy()
    nxt["year"] -= 1
    pairs = long.merge(nxt, on=["PATNO", "year"], suffixes=("_p", "_c"))
    for v in spec.tv:
        m = gen.models[("trans", v)]
        cur = {w: gen.marginals[w].score(pairs[f"{w}_c"].to_numpy()) for w in spec.tv}
        prev = {w: gen.marginals[w].score(pairs[f"{w}_p"].to_numpy()) for w in spec.tv}
        bs = {k: arr[pairs.PATNO.to_numpy()] for k, arr in sc_base.items()}
        X = _matrix(m.inputs, bs, cur, prev, len(pairs), t=0)
        tcol = [j for j, k in enumerate(m.inputs) if k == "t"]
        if tcol:
            X[:, tcol[0]] = pairs.year.to_numpy() + 1
        y = _mean(m, X)
        tot = np.var(y) + m.sigma ** 2 + m.trait ** 2
        for j, key in enumerate(m.inputs):
            Xp = X.copy()
            Xp[:, j] = rng.permutation(Xp[:, j])
            drop = max(0.0, (np.var(y - _mean(m, Xp))) / 2) / tot
            out[(key, v)] = float(np.sqrt(drop))
    for b in spec.baseline:
        m = gen.models.get(("base", b))
        for j, key in enumerate(m.inputs if m else []):
            out[(key, b)] = float(abs(m.coef[j]) / np.sqrt(np.sum(m.coef ** 2) + m.sigma ** 2 + m.trait ** 2))
    gen.strengths = out
    return out


def weak_pairs(gen: Generator, threshold: float = 0.05):
    """Two-slice pairs whose generating edge is near zero: excluded from the recoverable-truth metrics."""
    out = set()
    for (key, v), st in gen.strengths.items():
        if st >= threshold:
            continue
        child = f"{v}_1" if v in gen.spec.tv else v
        if key == "t" or key in gen.spec.baseline or key in E.CONTEXT:
            par = key
        elif key.endswith("@1"):
            par = f"{key[:-2]}_0"
        else:
            par = f"{key[:-2]}_1"
        out.add(frozenset((par, child)))
    return out


# ---------------------------------------------------------------------------- the synthetic generator
# PPMI-like marginals in clinical units (no PPMI data): used for tests and for the end-to-end synthetic runs.
def _synthetic_marginals():
    r = np.arange
    return {
        "age": _continuous(lambda g, n: np.clip(g.normal(62, 9.5, n), 30, 90), seed=1),
        "male": _discrete([0, 1], [0.37, 0.63]),
        "educ": _discrete(r(8, 21), [1, 1, 2, 3, 6, 6, 14, 6, 10, 9, 14, 8, 9]),
        "apoe4": _discrete([0, 1], [0.75, 0.25]),
        "dat0": _continuous(lambda g, n: np.clip(g.normal(1.4, 0.45, n), 0.3, 3.5), seed=2),
        "dur0": _continuous(lambda g, n: g.gamma(1.4, 14, n), seed=3),
        "ldopa": _continuous(lambda g, n: g.lognormal(np.log(420), 0.5, n), p0=0.45, seed=4),
        "da": _continuous(lambda g, n: g.lognormal(np.log(220), 0.6, n), p0=0.72, seed=5),
        "maob": _continuous(lambda g, n: np.where(g.random(n) < 0.6, 100.0, g.lognormal(np.log(80), 0.3, n)), p0=0.70, seed=6),
        "ama": _continuous(lambda g, n: g.lognormal(np.log(200), 0.3, n), p0=0.90, seed=7),
        "t_ldopa": _continuous(lambda g, n: g.uniform(3, 110, n), p0=0.45, seed=8),
        "cum_ldopa": _continuous(lambda g, n: g.lognormal(np.log(1.2), 0.9, n), p0=0.45, seed=9),
        "motor_na": _discrete(r(0, 61), norm.pdf(r(0, 61), 19, 9)),
        "axial": _discrete(r(0, 21), np.exp(-r(0, 21) / 3.0)),
        "adl": _discrete(r(0, 41), norm.pdf(r(0, 41), 8, 6) + 0.02),
        "se": _discrete([50, 60, 70, 80, 85, 90, 95, 100], [1, 2, 4, 9, 6, 30, 18, 30]),
        "fluct": _discrete(r(0, 9), [70, 8, 7, 6, 4, 2, 1.5, 1, 0.5]),
        "dysk": _discrete(r(0, 9), [85, 4, 4, 3, 2, 1, 0.5, 0.3, 0.2]),
        "ess": _discrete(r(0, 25), norm.pdf(r(0, 25), 7, 4.2)),
        "icd_core": _discrete(r(0, 5), [80, 12, 5, 2, 1]),
        "cog": _discrete(r(12, 31), np.exp(-((30 - r(12, 31)) / 3.2)) + 0.002),
        "dep": _discrete(r(0, 16), np.exp(-r(0, 16) / 2.6)),
        "hall": _discrete(r(0, 5), [90, 6, 2.5, 1, 0.5]),
    }


# Synthetic pooled design (PROTOCOL.md §6.1): cohort shares and follow-up as in the pooled PD cohorts
# (PPMI 1.0 de novo 431, PPMI 2.0 sporadic 957, genetic PD 353; 8.9 / 3.1 / 5.9 grid years per participant).
SYN_CONTEXT = {(0, 0): 0.25, (1, 0): 0.55, (0, 1): 0.12, (1, 1): 0.08}
SYN_FOLLOWUP = {(0, 0): (np.arange(1, 15), np.array([1, 1, 2, 3, 4, 5, 7, 9, 12, 14, 14, 12, 9, 7.0])),
                (1, 0): (np.arange(1, 7), np.array([12, 22, 26, 22, 12, 6.0])),
                (0, 1): (np.arange(1, 13), np.array([3, 5, 7, 9, 11, 12, 12, 11, 9, 8, 7, 6.0])),
                (1, 1): (np.arange(1, 7), np.array([12, 22, 26, 22, 12, 6.0]))}
SYN_CONTEXT_EDGES = (("era2", "t"), ("genetic", "t"), ("genetic", "age"), ("genetic", "dur0"), ("era2", "dur0"),
                     ("era2", "ldopa"), ("era2", "da"), ("genetic", "motor_na"), ("genetic", "cog"))
SYN_TRAIT = {"dep": 0.40, "ess": 0.30, "cog": -0.30, "motor_na": 0.20, "hall": 0.20, "icd_core": 0.20, "adl": 0.15,
             "dat0": -0.30}
SYN_AR = {"ldopa": 0.85, "da": 0.85, "maob": 0.85, "ama": 0.85, "t_ldopa": 0.90, "cum_ldopa": 0.92, "cog": 0.70}
SYN_TREND = {"ldopa": 0.15, "da": 0.06, "maob": 0.04, "ama": 0.05, "t_ldopa": 0.20, "cum_ldopa": 0.22}


def synthetic(kind: str = "G1", spec: E.ExpertSpec | None = None, seed: int = 20261029, person_sd: float = 0.35,
              calibrate_n: int = 4000) -> Generator:
    """A generator from the expert DAG alone: every expert edge gets a magnitude in [0.08, 0.35] (70% positive), the
    trait and autoregression strengths above, PPMI-like marginals, cohort mix and follow-up. G2 replaces the linear
    terms with non-monotone transforms and the Gaussian noise with t(5) noise."""
    spec = spec or E.load()
    rng = np.random.default_rng(seed)
    marg = _synthetic_marginals()
    models = {}
    ctx_eff = {("era2", "t"): 0.0, ("genetic", "t"): 0.0, ("genetic", "age"): -0.25, ("genetic", "dur0"): 0.45,
               ("era2", "dur0"): -0.20, ("era2", "ldopa"): 0.25, ("era2", "da"): -0.20, ("genetic", "motor_na"): 0.15,
               ("genetic", "cog"): -0.15}
    edge_eff = {}
    for a, b, k in spec.edges:
        if a in spec.latent:
            continue
        edge_eff[(a, b)] = rng.uniform(0.08, 0.35) * (1 if rng.random() < 0.7 else -1)
    tf_ids = list(_TRANSFORMS)

    def mk(v, regime):
        keys = _inputs(spec, v, regime, SYN_CONTEXT_EDGES)
        coef = []
        for key in keys:
            if key == "t":
                coef.append(SYN_TREND.get(v, 0.05))
            elif key == f"{v}@1":
                coef.append(SYN_AR.get(v, 0.6))
            elif key in E.CONTEXT:
                coef.append(ctx_eff[(key, v)])
            else:
                coef.append(edge_eff[(key.split("@")[0], v)])
        coef = np.array(coef, dtype=float)
        tr = None
        if kind == "G2":
            tr = ["lin" if (k == f"{v}@1" or k == "t" or k in E.CONTEXT) else tf_ids[int(rng.integers(len(tf_ids)))] for k in keys]
        return NodeModel(node=v, inputs=keys, coef=coef, transform=tr, noise="t5" if kind == "G2" else "normal",
                         sigma=0.75 if regime != "base" else 1.0, trait=SYN_TRAIT.get(v, 0.0),
                         person_sd=person_sd if regime != "base" else 0.0)

    for b in spec.baseline:
        models[("base", b)] = mk(b, "base")
    for v in spec.tv:
        models[("year0", v)] = mk(v, "year0")
        models[("trans", v)] = mk(v, "trans")
    # year 0: no one in PPMI 1.0 is on treatment at enrolment; later cohorts partly are (era and genetic shifts)
    for v in E.DOSE + ("t_ldopa", "cum_ldopa"):
        if ("year0", v) in models:
            models[("year0", v)].intercept = -1.6
    order = _within_year_order(spec)
    gen = Generator(kind=kind, spec=spec, marginals=marg, models=models, context_probs=dict(SYN_CONTEXT),
                    followup=dict(SYN_FOLLOWUP), context_edges=SYN_CONTEXT_EDGES, order0=order, order_t=order,
                    source=f"synthetic seed {seed}")
    return calibrate(gen, n=calibrate_n)
